def _generation_llm_config(self) -> RunLLMConfig:
    generation = _generation_settings(self.config)
    if str(generation.get("provider") or "api") == "codex":
        return self._codex_llm_config(model=str(generation.get("codex_model") or _retrieval_settings(self.config).get("codex_model") or ""), timeout_seconds=int(generation.get("timeout_seconds") or 120))
    return self._api_llm_config(model_override=str(generation.get("api_model") or ""), max_tokens_override=int(generation.get("max_tokens") or 4000), timeout_override=int(generation.get("timeout_seconds") or 120))
